// The worker pane's mascot: three rows of block glyphs and a caption, pure strings.
// register.js owns the clock and the drawing; this file only says what to show.

export const MASCOT_COLOR = 0xd97757
export const HELLO_MS = 2400
export const BYE_MS = 2400

export const MODEL_COLOR = {
  haiku: 0x9aa0a6,
  sonnet: 0x4f8ef7,
  opus: 0xf2a33a,
  fable: 0xa77bff,
  other: 0xc8c8c8,
}

export function modelKey(model) {
  const m = String(model ?? '').toLowerCase()
  for (const k of ['fable', 'opus', 'sonnet', 'haiku']) if (m.includes(k)) return k
  return 'other'
}

const HEAD = '  ▐▛███▜▌'
const BODY = ' ▝▜█████▛▘'
const LEGS = ['   ▘▘ ▝▝', '   ▝▝ ▘▘']
const ARM = { hi: ' ╱', bye: ' ╲' }

// One small accessory per role, so the band shows who is who: a swapped head or body row,
// same width class, single-cell glyphs only. A role without an entry wears nothing.
export const ACCESSORY = {
  executor: { head: '  ▟▛███▜▙' },             // hard hat
  planner: { head: '  ▐▛█▲█▜▌' },              // thinking cap
  'plan-reviewer': { head: '  ▐▛███◉▌' },      // monocle
  'code-reviewer': { head: '  ▐▛○─○▜▌' },      // glasses
  'security-reviewer': { body: ' ▝▜█▚▄▞█▛▘' }, // moustache
  'design-reviewer': { body: ' ▝▜█▶▪◀█▛▘' },    // bow tie
  adversary: { head: ' ◥▐▛███▜▌◤' },           // horns
  'payments-reviewer': { body: ' ▝▜██$██▛▘' }, // dollar sign
  'perf-reviewer': { head: '  ▌▛███▜▐' },      // headphones
}

// mood: 'hi' | 'working' | 'bye'. Three rows; the legs step on every other tick while working.
export function frame(mood, tick = 0, role = '') {
  const wear = ACCESSORY[role] ?? {}
  return [(wear.head ?? HEAD) + (ARM[mood] ?? ''), wear.body ?? BODY, LEGS[mood === 'working' ? tick & 1 : 0]]
}

const mmss = (ms) => {
  const s = Math.max(0, Math.round(ms / 1000))
  return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0')
}

export function caption({ mood, agent, model, effort, ms }) {
  const who = [agent, model, effort].filter(Boolean).join(' · ')
  if (mood === 'hi') return 'hi! ' + who
  if (mood === 'working') return agent + ' · working ' + mmss(ms ?? 0)
  if (mood === 'bye') return 'bye! ✓ done ' + mmss(ms ?? 0)
  return who + (ms != null ? ' · done ' + mmss(ms) : '')
}

// hi outranks the rest until it is over; 'idle' means nothing is animating.
export function moodAt({ hiUntil = 0, byeUntil = 0, working = false, now }) {
  if (now < hiUntil) return 'hi'
  if (now < byeUntil) return 'bye'
  return working ? 'working' : 'idle'
}

// The deck's cast: a subagent says hi for its first HELLO_MS, steps while it works, and waves
// bye once it finishes.
export function agentMood(a, now) {
  if (a.state !== 'working') return 'bye'
  return now - a.start < HELLO_MS ? 'hi' : 'working'
}

// AGENTILLE_WORKER=<agent>:<model>:<effort>, set when the lead opens the pane; effort may be empty.
export function parseWorker(text) {
  const [agent, model, effort = ''] = String(text ?? '').split(':')
  return /^[a-z][a-z-]*$/.test(agent) && /^[\w.-]+$/.test(model ?? '') ? { agent, model, effort } : null
}

files.hooks/highlight.js:
// agentille highlight — make a long /agt reply scannable. Pure on purpose: register.js
// draws; these helpers decide what to light and what goes on the essentials card.
//
//   essentials — the next action, the one flag, the one done line, read off the text. No model.
//                 Skipped for a final card (an answer opening with ✓ or ✗): it would repeat it.
//   lightTokens — wrap paths, versions, refs and numbers in backticks so the dim body
//                 shows them lit. Code, links and fences are never touched.

import { words } from './focus.js'

export const CARD_MIN_WORDS = 40
export const LIT_MAX = 10_000
export const LIT_MEMO_MAX = 500
export const MARK = { next: '→', flag: '⚑', done: '✓' }
export const SPAN_COLOR = { path: '#7fd3e6', cmd: '#4f8ef7', version: '#a77bff', number: '#f2a33a', ref: '#3fb950' }
export const HIGHLIGHT_USAGE = 'Usage: /agt-highlight [on|all|off]'

const MAX_LINE = 96

const PATH_ABS = /^(~\/|\.{1,2}\/|\/)[\w@.\/-]*[\w@-](:\d+(-\d+)?)?$/
const PATH_REL = /^[\w@.-]+(\/[\w@.-]+)+\.[A-Za-z0-9]{1,8}(:\d+(-\d+)?)?$/
const VERSION = /^v?\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$|^v\d+(\.\d+)?$/
const REF = /^#\d+$/
const NUMBER = /^\d+([.,]\d+)?(×|x|%|k|K|M|ms|s|min)$/

function kindOf(core) {
  if (core.includes('://')) return null
  if (PATH_ABS.test(core) || PATH_REL.test(core)) return 'path'
  if (VERSION.test(core)) return 'version'
  if (REF.test(core)) return 'ref'
  if (NUMBER.test(core)) return 'number'
  return null
}

// Punctuation that hugs a token is not part of it: "(#75)," lights #75 only.
function peel(token) {
  const lead = /^(?:[(\[{"'*_]|~(?!\/))+/.exec(token)?.[0] ?? ''
  const rest = token.slice(lead.length)
  const trail = /[.,;:!?)\]}"'*_…]+$/.exec(rest)?.[0] ?? ''
  return { lead, core: rest.slice(0, rest.length - trail.length), trail }
}

// A fence opens at any indent (list items nest them) and closes only on the same
// character, at least as long, alone on its line. An unclosed fence runs to the end.
function fenceMask(lines) {
  let open = null
  return lines.map((l) => {
    // Quoted code blocks fence the same way: `> ```` opens one too.
    l = l.replace(/^\s*(?:>\s?)+/, '')
    if (open) {
      const c = /^\s*(`+|~+)\s*$/.exec(l)
      if (c && c[1][0] === open[0] && c[1].length >= open.length) open = null
      return true
    }
    // A backtick fence's info string has no backtick, so ```npm test``` is inline code.
    const m = /^\s*(`{3,})[^`]*$/.exec(l) ?? /^\s*(~{3,})/.exec(l)
    if (m) {
      open = m[1]
      return true
    }
    return false
  })
}

const PROTECTED = /(`[^`]*`|!?\[[^\]]*\]\([^)]*\)|<[^>\s]+>)/

function lightPlain(seg) {
  return seg
    .split(/(\s+)/)
    .map((tok) => {
      if (!tok.trim() || tok.includes('://') || tok.startsWith('www.')) return tok
      const { lead, core, trail } = peel(tok)
      return core && kindOf(core) ? lead + '`' + core + '`' + trail : tok
    })
    .join('')
}

export function lightTokens(md) {
  const lines = String(md ?? '').split('\n')
  const fenced = fenceMask(lines)
  return lines
    .map((l, i) => {
      if (fenced[i]) return l
      if (/^\s{0,3}\[[^\]]+\]:/.test(l)) return l
      if ((l.match(/`/g) ?? []).length % 2) return l
      return l.split(PROTECTED).map((seg, j) => (j % 2 ? seg : lightPlain(seg))).join('')
    })
    .join('\n')
}

function clip(s) {
  const t = s.replace(/\s+/g, ' ').trim()
  return t.length > MAX_LINE ? t.slice(0, MAX_LINE - 1) + '…' : t
}

const NEGATED = /\b(0|no|zero|without)\s+(\w+\s+)?(failures?|failed|failing|fails?|errors?|warnings?|blockers?)\b/gi

function isFlag(line) {
  const t = line.replace(NEGATED, '')
  return (
    /[⚑✗]/.test(t) ||
    /\b(blockers?|blocked|failed|failing)\b/i.test(t) ||
    /\b(FAIL|CONCERNS|REVISE)\b/.test(t) ||
    /needs you/i.test(t) ||
    /\b[1-9]\d*\s+(\w+\s+)?(errors?|warnings?)\b/i.test(t) ||
    /^(error|warning):/i.test(t)
  )
}

function isDone(line) {
  if (/\bnot\s+(yet\s+)?(done|merged|released|passing)\b/i.test(line)) return false
  return /[✓✅]/.test(line) || /\b(done|passes|passed|passing|merged|released|shipped|tagged|green)\b/i.test(line)
}

function nextText(line) {
  if (line.startsWith('→')) return line.slice(1).trim()
  const m = /^next(?: steps?)?\s*[:—-]\s*(.*)$/i.exec(line)
  if (m) return m[1].trim()
  return /next step/i.test(line) ? line : ''
}

// → [{ kind, text }]: at most one per kind, first line wins, next · flag · done.
export function essentials(text) {
  const lines = String(text ?? '').split('\n')
  const fenced = fenceMask(lines)
  const found = {}
  lines.forEach((raw, i) => {
    if (fenced[i]) return
    if (/^\s*#{1,6}(\s|$)/.test(raw)) return
    if (/^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/.test(raw)) return
    const line = raw
      .replace(/^\s*(?:(?:[-*+]|\d+[.)])\s+|>\s*)+/, '')
      .replace(/\*\*|__/g, '')
      .trim()
    if (!line) return
    const next = !found.next && nextText(line)
    if (next) {
      found.next = clip(next)
      return
    }
    if (!found.flag && isFlag(line)) {
      const t = clip(line.replace(/^⚑️?\s*/, ''))
      if (t) found.flag = t
      return
    }
    if (isFlag(line)) return // a second flag is still a flag, never the done line
    if (!found.done && isDone(line)) {
      const t = clip(line.replace(/^[✓✅]️?\s*/, ''))
      if (t) found.done = t
    }
  })
  return ['next', 'flag', 'done'].filter((k) => found[k]).map((kind) => ({ kind, text: found[kind] }))
}

// A line → coloured pieces. Backtick delimiters are dropped; the texts rejoin to the line.
export function spans(line) {
  const out = []
  const push = (text, kind) => {
    if (!text) return
    const last = out[out.length - 1]
    if (kind === 'plain' && last?.kind === 'plain') last.text += text
    else out.push({ text, kind })
  }
  String(line ?? '').split(/`([^`]*)`/).forEach((seg, j) => {
    if (j % 2) return push(seg, kindOf(seg) ?? 'cmd')
    for (const tok of seg.split(/(\s+)/)) {
      if (!tok.trim()) {
        push(tok, 'plain')
        continue
      }
      const { lead, core, trail } = peel(tok)
      const kind = !core ? 'plain' : /^\/[a-z][\w:-]*$/.test(core) ? 'cmd' : (kindOf(core) ?? 'plain')
      push(lead, 'plain')
      push(core, kind)
      push(trail, 'plain')
    }
  })
  return out
}

// The run's final card opens with ✓ (done) or ✗ (failed): it is its own summary, so no
// essentials card and no word floor, only the tokens lit.
const isFinalCard = (text) => /^[✓✗]/.test(String(text ?? '').trimStart())

export function highlight(text) {
  const final = isFinalCard(text)
  if (!final && words(text) < CARD_MIN_WORDS) return null
  const card = final ? [] : essentials(text)
  const lit = lightTokens(text)
  const body = lit.length <= LIT_MAX ? lit : null
  if (!card.length && body === null) return null
  return { card, body }
}

// The lit/dim decision is made once per message id, on its first sight, so a reply
// does not flip style when a later turn changes.
export function litFor(memo, id, { on, agtTurn }) {
  if (!id) return !!(on && agtTurn)
  if (!memo.has(id)) {
    memo.set(id, !!agtTurn)
    if (memo.size > LIT_MEMO_MAX) memo.delete(memo.keys().next().value)
  }
  return !!on && memo.get(id)
}

export function parseHighlightArgs(args) {
  const a = String(args ?? '').trim().toLowerCase()
  if (!a) return { show: true }
  if (a === 'on') return { on: true, all: false }
  if (a === 'all') return { on: true, all: true }
  if (a === 'off') return { on: false, all: false }
  return { error: HIGHLIGHT_USAGE }
}

export function highlightText(on, all = false) {
  if (!on) return 'Highlight: off — replies draw as usual. /agt-highlight on turns it back on.'
  const which = all ? 'all — every long reply gets' : 'on — /agt replies get'
  return 'Highlight: ' + which + ' an essentials card and a dim body with paths, versions, refs and numbers lit.' + (all ? '' : ' /agt-highlight all covers plain prompts too.')
}

files.hooks/focus.js:
// agentille focus — what in a run needs the reader. Pure on purpose: register.js draws.
//
// Flags are read straight off agent results (a REVISE, a FAIL verdict, a failed check, a
// blocked pane). No model call.

export function words(text) {
  const t = String(text ?? '').trim()
  return t ? t.split(/\s+/).length : 0
}

// One agent's final answer → a flag line, or null. Reviewers share `VERDICT: PASS|CONCERNS|FAIL`;
// the executor's VERIFICATION block carries real exit codes and counts.
export function flagOf(role, answer) {
  const a = String(answer ?? '')
  // The first verdict word decides, as routing.js verdictOf reads it: "APPROVE — nothing warrants a REVISE" is an approval.
  if (role === 'plan-reviewer' && /\b(APPROVE|REVISE)\b/.exec(a)?.[1] === 'REVISE') return role + ' asked for a revised plan'
  const v = /VERDICT:\s*(FAIL|CONCERNS)\b/.exec(a)
  if (v && role.endsWith('reviewer')) return role + ': ' + v[1] + (v[1] === 'FAIL' ? ' — blocks ship' : ' — fix before ship')
  if (role === 'adversary') {
    const b = /\bBROKEN:\s*([1-9]\d*)/.exec(a)
    if (b) return 'adversary broke ' + b[1] + ' case' + (b[1] === '1' ? '' : 's')
  }
  if (role === 'executor') {
    const ver = (/VERIFICATION:([\s\S]*?)(\n[A-Z]+:|$)/.exec(a) ?? [])[1] ?? ''
    if (/exit(?:\s*code)?\s*[:=]?\s*[1-9]\d*/i.test(ver) || /\b[1-9]\d* (failed|failing|fail|errors?)\b/i.test(ver)) return 'executor: verification failed'
    if (/did not run|not run|couldn'?t run|could not run/i.test(ver)) return 'executor: verification not run'
    if (/^CONTEXT\s/m.test(a)) return 'executor handed off at its context limit'
  }
  return null
}

// Panes that wait on a person: herdr reports `blocked` when an approval is on screen.
export function paneFlags(panes) {
  return (panes ?? []).filter((p) => p.state === 'blocked').map((p) => p.name + ' is waiting on you')
}

// /agt-focus arguments → { on } | { show: true } | { error }
export function parseFocusArgs(args) {
  const a = String(args ?? '').trim().toLowerCase()
  if (!a) return { show: true }
  return a === 'on' || a === 'off' ? { on: a === 'on' } : { error: 'Usage: /agt-focus [on|off]' }
}

export function focusText(on, flags) {
  const head = 'focus: ' + (on ? 'on (agent flags show above the prompt)' : 'off (no flags above the prompt)')
  return flags.length ? head + '\n' + flags.map((f) => '⚑ ' + f).join('\n') : head + '\nNothing to flag right now.'
}

files.hooks/panes.js:
// Pane transport: which multiplexer this session runs in (Herdr, tmux, or none), how to
// open a worker pane in it, and how to read tmux panes back as live.js pane agents.
// Pure on purpose — the hooks loader never follows `$` across an import — so every
// $.process / $.env / $.fs call lives in register.js and only feeds these helpers.

import { ROLES, parseHeader } from './routing.js'

export const SAFE_RUN = /^[A-Za-z0-9_-]{1,64}$/
export const NAME_RE = /^[a-z][a-z0-9_-]{0,31}$/
const ROLE_RE = /^[a-z0-9-]+$/
const MODEL_LIKE = /^[A-Za-z0-9][\w.-]*$/
const BARE_WORD = /^[a-z-]+$/
const MODEL_RE = /^(haiku|sonnet|opus|fable|claude-[a-z0-9.-]+)$/
export const PROBE = { timeoutMs: 5000 }
export const HERDR_START_TIMEOUT = { timeoutMs: 60000 }
const TAB = '\t'

export const SPAWN_ROLE = 'spawn'
export const DEFAULT_MODEL = 'sonnet'
export const SPAWN_USAGE = 'Usage: /agt-spawn "task" [--model sonnet|opus|haiku|fable]'

// herdr when HERDR_ENV=1 and `herdr --version` ran; else tmux when $TMUX is set and
// `tmux -V` ran; else none. Callers pass what their probes found (a probe that rejects
// or exits non-zero is false).
export function pickTransport({ herdrOk, tmuxOk }) {
  return herdrOk ? 'herdr' : tmuxOk ? 'tmux' : 'none'
}

export const PANE_RULE = 'Pane rule: panes only when ≥2 slices build at once or `--mode panes`: each slice\'s executor (and the adversary) via spawn_pane (agent + header); everyone else is a subagent. close_pane after harvest.'

// The block appended to the /agt skill prompt: which transport is live and, when the mod
// registered the pane tools, the rule for using them.
export function transportBlock(transport, tools = false) {
  const note = transport === 'none' ? 'No pane transport here: parallel slices run as a workflow, else subagent waves.\n' : tools ? PANE_RULE + '\n' : ''
  return '\n## Pane transport (agentille mod)\n\ntransport: ' + transport + '\n' + note
}

// ── names ─────────────────────────────────────────────────────────────────────

export function paneName(run, role) {
  const name = 'agt-' + run + '-' + role
  return SAFE_RUN.test(run) && ROLE_RE.test(role) && NAME_RE.test(name) ? name : null
}

export function newRunId() {
  let id = ''
  while (id.length < 6) id += Math.floor(Math.random() * 36).toString(36)
  return id
}

// `agt-<run>-<role…>` → { run, role } with both safe to put in a path, else null.
export function splitName(name) {
  const parts = String(name ?? '').split('-')
  if (parts[0] !== 'agt' || parts.length < 3) return null
  const run = parts[1]
  const role = parts.slice(2).join('-')
  return SAFE_RUN.test(run) && ROLE_RE.test(role) ? { run, role } : null
}

export function doneFile(home, run, role) {
  if (!home || !SAFE_RUN.test(run) || !ROLE_RE.test(role)) return null
  return home + '/.agentille/state/run-' + run + '/done-' + role
}

// ── /agt-spawn arguments ──────────────────────────────────────────────────────

// `"task" --model haiku` → { task, model }. `--model` counts as the flag only when it stands
// alone before a model-looking token; "explain the --model flag" stays prose. One matching pair of
// surrounding quotes is stripped. { usage } for a missing task, { error } for a bad model or a
// single bare word (claude would run it as a subcommand).
export function parseSpawnArgs(args) {
  let model = DEFAULT_MODEL
  let bad = null
  let taken = false
  const rest = String(args ?? '').replace(/(^|\s)--model(?:\s+|=)(\S+)(?=\s|$)/g, (whole, _lead, m) => {
    if (taken) return whole
    if (MODEL_RE.test(m)) model = m
    else if (MODEL_LIKE.test(m) && /[^a-z]/.test(m)) bad = m
    else return whole
    taken = true
    return ''
  }).trim()
  if (bad) return { error: 'Unknown model "' + bad + '". ' + SPAWN_USAGE }
  const task = rest.replace(/^(["'])((?:(?!\1)[\s\S])*)\1$/, '$2').trim()
  if (BARE_WORD.test(task)) return { error: 'A one-word task would run as a claude subcommand. Say more. ' + SPAWN_USAGE }
  return task ? { task, model } : { usage: SPAWN_USAGE }
}

// ── tmux ──────────────────────────────────────────────────────────────────────

export const TMUX_LIST_FORMAT = ['#{pane_id}', '#{@agt}', '#{@agt_vendor}', '#{pane_dead}', '#{window_id}'].join(TAB)

export function parseTmuxList(stdout) {
  return String(stdout ?? '').split('\n').filter(Boolean).map((line) => {
    const [id, agt, vendor, dead, window] = line.split(TAB)
    return { id, agt: agt ?? '', vendor: vendor ?? '', dead: dead === '1', window: window ?? '' }
  }).filter((r) => r.id)
}

// The agt- panes a lead looks at: not itself, and only in its own window. Without a known
// self (its pane is missing from the list) nothing is window-scoped, so nothing is trusted.
export function scopeRows(rows, selfPane) {
  const me = rows.find((r) => r.id === selfPane)
  return rows.filter((r) => r.agt.startsWith('agt-') && r.id !== selfPane && (!me || r.window === me.window))
}

// A done-file counts only if it was written once the pane was already known: a file left by
// an earlier worker of the same role must not mark the new one done.
export function isFreshDone(stat, since) {
  return stat?.kind === 'file' && typeof stat.mtimeMs === 'number' && typeof since === 'number' && stat.mtimeMs >= since
}

// /agt-spawn panes are the person's, not a run's: shown as `open`, never as working or done,
// so they feed no spinner, busy timer or working count.
export function quietSpawn(panes) {
  return panes.map((p) => (p.role === SPAWN_ROLE ? { ...p, state: 'open', seq: 0 } : p))
}

// tmux rows → live.js pane agents. `done` maps pane name → whether a fresh done-file exists.
// A pane is done when that holds or tmux says it is dead; seq is synthesized for reapable().
export function tmuxPaneAgents(rows, selfPane, done) {
  return quietSpawn(scopeRows(rows, selfPane).map((r) => {
    const n = splitName(r.agt)
    const finished = r.dead || done.get(r.agt) === true
    return { id: r.id, kind: 'pane', name: r.agt, role: n?.role ?? r.agt, run: n?.run ?? '', vendor: r.vendor || 'claude', state: finished ? 'done' : 'working', seq: finished ? 1 : 0, tab: r.window, workspace: null }
  }))
}

// Only a pane with no @agt name of its own is a lead; workers never reap.
export function isLead(rows, selfPane) {
  const me = rows.find((r) => r.id === selfPane)
  return !!me && !me.agt.startsWith('agt-')
}

export const TMUX_LIST_ARGV = ['tmux', 'list-panes', '-a', '-F', TMUX_LIST_FORMAT]

// ── reaping ───────────────────────────────────────────────────────────────────

// /agt-spawn panes belong to the person, not to a run: never offered to the reaper.
export function reapPool(panes) {
  return panes.filter((p) => p.role !== SPAWN_ROLE)
}

// ── spawning ──────────────────────────────────────────────────────────────────

export const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max']
const effortArgs = (effort) => (EFFORTS.includes(effort) ? ['--effort', effort] : [])
// A routed worker runs as its agentille agent definition (instructions, tools, verdict format),
// not as a bare session that only has the task prompt.
const agentArgs = (agent) => (ROLES.includes(agent) ? ['--agent', 'agentille:agentille-' + agent] : [])

// Who the worker is, for its own mascot band: <agent>:<model>:<effort>. A typed /agt-spawn has no agent.
export const workerEnv = ({ agent, model, effort }) => 'AGENTILLE_WORKER=' + [agent || SPAWN_ROLE, model, EFFORTS.includes(effort) ? effort : ''].join(':')

export function tmuxSplitArgv({ target, cwd, run, shell, model, name, task, effort, direction, agent, env = [] }) {
  const head = ['tmux', 'split-window', '-d', direction === 'down' ? '-v' : '-h', '-P', '-F', '#{pane_id}', '-t', target, '-c', cwd.replace(/#/g, '##'), '-e', 'AGENTILLE_RUN=' + run, '-e', workerEnv({ agent, model, effort }), ...env.flatMap((v) => ['-e', v])]
  // `--` ends claude's options, so a task that starts with `-` is still just the prompt
  const tail = [...agentArgs(agent), '--model', model, ...effortArgs(effort), '-n', name, '--', task]
  const base = String(shell ?? '').split('/').pop()
  if (base === 'zsh' || base === 'bash') return [...head, shell, '-ic', 'claude "$@"', 'agt', ...tail]
  return [...head, 'claude', ...tail]
}

// Stacked layout: the first worker splits right of the lead, each later one splits down from the
// newest worker still live. No width probing: a stack always has room for one more row.
export function splitPlan({ lead, opened = [], live = [] }) {
  const alive = opened.filter((o) => live.some((p) => p.id === o.id))
  return alive.length ? { target: alive[alive.length - 1].id, direction: 'down' } : { target: lead, direction: 'right' }
}

export const tmuxEvenArgv = (id) => ['tmux', 'select-layout', '-E', '-t', id]

export function tmuxTagArgvs(id, name) {
  return [
    ['tmux', 'set-option', '-p', '-t', id, '@agt', name],
    ['tmux', 'set-option', '-p', '-t', id, '@agt_vendor', 'claude'],
    ['tmux', 'set-option', '-p', '-t', id, 'allow-set-title', 'off'],
    ['tmux', 'select-pane', '-t', id, '-T', name],
  ]
}

export function tmuxPaneIdOf(stdout) {
  const id = String(stdout ?? '').trim()
  return /^%\d+$/.test(id) ? id : null
}

export const tmuxKillArgv = (id) => ['tmux', 'kill-pane', '-t', id]

// herdr: split beside the lead (never focused), start claude in it, then prompt it.
export function herdrSplitArgv({ pane, cwd, run, direction, agent, model, effort, env = [] }) {
  return ['herdr', 'pane', 'split', '--pane', pane, '--direction', direction === 'down' ? 'down' : 'right', '--cwd', cwd, '--env', 'AGENTILLE_RUN=' + run, '--env', workerEnv({ agent, model, effort }), ...env.flatMap((v) => ['--env', v]), '--no-focus']
}

export function herdrPaneIdOf(stdout) {
  try {
    return JSON.parse(stdout).result?.pane?.pane_id ?? null
  } catch {
    return null
  }
}

export const herdrStartArgv = ({ name, pane, model, effort, agent }) => ['herdr', 'agent', 'start', name, '--kind', 'claude', '--pane', pane, '--timeout', '45000', '--', ...agentArgs(agent), '--model', model, ...effortArgs(effort)]
export const herdrPromptArgv = (name, task) => ['herdr', 'agent', 'prompt', name, task]
export const herdrCloseArgv = (id) => ['herdr', 'pane', 'close', id]

// Herdr's sidebar label for a worker pane (display-only; a failure changes nothing).
export function herdrMetaArgv(pane, { display = null, title = null } = {}) {
  // herdr reads the pane id before the options
  const argv = ['herdr', 'pane', 'report-metadata', pane, '--source', 'agentille']
  if (display) argv.push('--display-agent', String(display).slice(0, 48))
  if (title) argv.push('--title', String(title).slice(0, 64))
  return argv.length > 6 ? argv : null
}

// Jump to a worker from its band row: Herdr focuses the agent by name, tmux selects the pane.
export function focusArgv(transport, pane) {
  if (transport === 'herdr' && pane?.name) return ['herdr', 'agent', 'focus', pane.name]
  if (transport === 'tmux' && /^%\d+$/.test(String(pane?.id ?? ''))) return ['tmux', 'select-pane', '-t', pane.id]
  return null
}

// Whether a routing role runs as a pane worker: only an executor or the adversary. Reviewers and the
// planning roles stay subagents: their flags, token counts and full answers exist only there.
export function paneRole(agent) {
  return agent === 'executor' || agent === 'adversary'
    ? { pane: true, why: '' }
    : { pane: false, why: `${agent} runs as a subagent: only an executor or the adversary gets a pane.` }
}

// ── pane tools: /agt panes mode opens and closes workers through the mod ──────

// Fable is not offered: on a tool it would skip the routing guard. A typed /agt-spawn may still pick it.
export const TOOL_MODELS = ['sonnet', 'opus', 'haiku']

export const SPAWN_TOOL = {
  name: 'spawn_pane',
  description: 'Open one agentille worker pane beside this session (Herdr or tmux, whichever is live), never focused, named agt-<run>-<role>, running Claude on the model and effort agentille routes for `agent`, with the task as its first prompt. Use it for each panes-mode slice in place of raw herdr/tmux commands. The pane is reaped once it sits done; close it yourself with close_pane after harvesting.',
  inputSchema: {
    type: 'object',
    properties: {
      run: { type: 'string', description: 'The run id from the [agt run=…] header (6 chars).' },
      role: { type: 'string', description: 'Slice role, lowercase letters, digits and dashes (exec-1, review). Not "spawn".' },
      task: { type: 'string', description: 'The full self-contained worker prompt.' },
      agent: { type: 'string', enum: ROLES, description: 'Routing role (executor, code-reviewer, …): the mod routes model and effort from it.' },
      header: { type: 'string', description: 'This run\'s full [agt run=… size=… risk=… mode=… fable=…] line.' },
      model: { type: 'string', enum: TOOL_MODELS, description: 'Ignored: the mod routes model and effort from agent + header. Kept so older prompts validate.' },
      cwd: { type: 'string', description: 'Absolute directory to start in (the slice worktree). Default: this session\'s directory.' },
    },
    required: ['run', 'role', 'task', 'agent', 'header'],
    additionalProperties: false,
  },
}

export const CLOSE_TOOL = {
  name: 'close_pane',
  description: 'Close one agentille worker pane this session opened (an agt-<run>-<role> pane in this tab or window) after you have read its result. Panes opened by a typed /agt-spawn and panes of other sessions are refused.',
  inputSchema: {
    type: 'object',
    properties: { name: { type: 'string', description: 'The pane name, agt-<run>-<role>.' } },
    required: ['name'],
    additionalProperties: false,
  },
}

// spawn_pane input → { run, role, name, agent, header, hdr, asked, model, task, cwd } or { error }. `live` is the
// panes the mod sees now; a name already on screen is refused rather than doubled.
export function spawnToolInput(input, live = []) {
  const i = input ?? {}
  const str = (v) => (typeof v === 'string' ? v.trim() : '')
  const run = str(i.run)
  const role = str(i.role)
  const task = str(i.task)
  const agent = str(i.agent)
  const header = str(i.header)
  const asked = str(i.model) || null
  const model = asked ?? DEFAULT_MODEL
  const cwd = i.cwd === undefined ? null : str(i.cwd)
  if (!SAFE_RUN.test(run)) return { error: 'run must be the run id from the [agt run=…] header.' }
  if (!ROLE_RE.test(role)) return { error: 'role must be lowercase letters, digits and dashes.' }
  if (role === SPAWN_ROLE) return { error: '"spawn" is reserved for a typed /agt-spawn.' }
  const name = paneName(run, role)
  if (!name) return { error: 'agt-' + run + '-' + role + ' is not a valid pane name (max 32 chars).' }
  if (!ROLES.includes(agent)) return { error: 'agent must be one of ' + ROLES.join(', ') + '.' }
  const hdr = parseHeader(header)
  if (!hdr) return { error: 'header must be the run\'s [agt run=… …] line.' }
  if (hdr.run !== run) return { error: 'header run=' + hdr.run + ' does not match run ' + run + '.' }
  if (!TOOL_MODELS.includes(model)) return { error: 'model must be one of ' + TOOL_MODELS.join(', ') + '. Fable runs only through the routing guard or a typed /agt-spawn.' }
  if (!task) return { error: 'task is empty.' }
  if (BARE_WORD.test(task)) return { error: 'A one-word task would run as a claude subcommand. Send the full worker prompt.' }
  if (cwd !== null && (!cwd.startsWith('/') || cwd.includes('\0'))) return { error: 'cwd must be an absolute path.' }
  if (live.some((p) => p.name === name)) return { error: name + ' is already open. Pick another role or close it first.' }
  return { run, role, name, agent, header, hdr, asked, model, task, cwd }
}

// close_pane input → { pane } from the panes this session owns, or { error }. `tab`, when
// given, keeps a herdr close inside the lead's own tab.
export function closeTarget(input, live = [], tab = null) {
  const name = typeof input?.name === 'string' ? input.name.trim() : ''
  const n = splitName(name)
  if (!n) return { error: 'name must be an agt-<run>-<role> pane name.' }
  if (n.role === SPAWN_ROLE) return { error: name + ' was opened by a typed /agt-spawn; it is the person\'s to close.' }
  const pane = live.find((p) => p.name === name && (tab === null || p.tab === tab))
  return pane ? { pane } : { error: 'No pane named ' + name + ' in this tab or window.' }
}
